5	.no-header {
6	  $root: &;
7	  position: fixed;
8	  top: 0;
9	  left: 0;
10	  right: 0;
11	  width: 100%;
12	  height: var(--header-height);
13	  background: transparent;
14	  z-index: var(--z-index-header);
15	  overflow: visible;
16	  transition: var(--transition-default);
17	  transform: translateY(0);
18	  opacity: 1;
19	  border-bottom: 1px solid var(--clr-border-default);
20	  html.is-intro & {
21	    transform: translateY(-100%);
22	    opacity: 0;
23	    pointer-events: none;
24	  }
25	
26	  &.visual {
27	    background: var(--clr-surface-weak);
28	    backdrop-filter: blur(2px);
29	    -webkit-backdrop-filter: blur(2px);
30	  }
31	
32	  &[aria-expanded="true"] {
33	    background: var(--clr-ui-bg);
34	    #{$root}__inner {
35	      border-color: var(--clr-border-default);
36	    }
37	  }
38	
39	  &.visual[aria-expanded="true"] {
40	    background: var(--clr-background-active);
41	  }
42	
43	  &__inner {
44	    position: relative;
45	    z-index: calc(var(--z-index-drawer) + 1);
46	    @include flex-center();
47	    height: var(--header-height);
48	    transition: var(--transition-default);
49	    border-bottom: 1px solid transparent;
50	  }
51	
52	  &__wrap {
53	    display: flex;
54	    align-items: center;
55	    gap: var(--gutter-sm);
56	    height: var(--header-height);
57	    width: 100%;
58	  }
59	
60	  &-right {
61	    display: flex;
62	    align-items: center;
63	    gap: var(--gutter-sm);
64	  }
65	
66	  &__nav {
67	    display: flex;
68	    align-items: center;
69	    height: 100%;
70	  }
71	
72	  &__gnb {
73	    display: flex;
74	    align-items: center;
75	    gap: var(--gutter-lg);
76	  }
77	
78	  &__gnb-item {
79	    position: relative;
80	    display: flex;
81	    align-items: center;
82	    gap: var(--gutter-xs);
83	  }
84	
85	  &__gnb-link {
86	    display: inline-flex;
87	    align-items: center;
88	    color: var(--clr-text-title);
89	    font-family: var(--family-en-title);
90	    @include font("f-body-1");
91	    font-weight: 600;
92	    text-decoration: none;
93	    letter-spacing: fluid(0, 1);
94	    transition: var(--transition-fast);
95	
96	    &:hover {
97	      color: var(--clr-text-body);
98	    }
99	
100	    &.is-active {
101	      color: var(--clr-primary-300);
102	    }
103	  }
104	
105	  &__works-signboard {
106	    display: inline-flex;
107	    align-items: center;
108	    justify-content: center;
109	    margin-left: var(--gutter-2xs);
110	    padding: 0 var(--gutter-xs);
111	    border-radius: 999px;
112	    background: var(--clr-white-24);
113	    backdrop-filter: blur(6px);
114	    -webkit-backdrop-filter: blur(6px);
115	  }
116	
117	  &__works-signboard__count {
118	    display: block;
119	    @include font("f-body-3");
120	    color: var(--clr-text-title);
121	  }
122	
123	  &__container {
124	    display: flex;
125	    justify-content: space-between;
126	    align-items: center;
127	    height: var(--header-height);
128	    width: 100%;
129	    padding: 0 var(--gutter-container);
130	  }
131	
132	  &__logo {
133	    @include flex-center();
134	    svg {
135	      display: block;
136	      height: auto;
137	      width: fluid(140, 180);
138	    }
139	  }
140	
141	  &__action {
142	    @include flex-center();
143	    gap: var(--gutter-sm);
144	  }
145	
146	  &__menu-btn {
147	    @include flex-center();
148	    width: fluid(36, 44);
149	    height: fluid(36, 44);
150	    padding: 0 !important;
151	    color: var(--clr-text-title);
152	    cursor: pointer;
153	    border: 1px solid var(--clr-border-default);
154	    border-radius: var(--scrollbar-radius);
155	    transition: var(--transition-fast);
156	
157	    .no-corner-btn__icon {
158	      margin: 0;
159	      svg {
160	        width: fluid(14, 20);
161	        height: fluid(14, 20);
162	        transition: transform var(--transition-fast);
163	      }
164	    }
165	
166	    &[aria-expanded="true"] .no-corner-btn__icon svg,
167	    &:hover .no-corner-btn__icon svg {
168	      transform: rotate(45deg);
169	    }
170	
171	    &:hover .no-corner-btn__icon svg {
172	      width: fluid(16, 20);
173	      height: fluid(16, 20);
174	    }
175	  }
176	}
