560	  private _applyAboutWhoShowcaseState(
561	    titleLayers: readonly HTMLElement[],
562	    ring: HTMLElement,
563	    cards: readonly HTMLElement[],
564	    progress: number,
565	  ): void {
566	    const cardCount = Math.max(cards.length, 1);
567	    const spawnProgress = this._easeOutCubic(
568	      Helpers.remap01(progress, 0, ABOUT_WHO_SHOWCASE.spawnEnd),
569	    );
570	    const mergeProgress = this._easeInOutCubic(
571	      Helpers.remap01(
572	        progress,
573	        ABOUT_WHO_SHOWCASE.cardRevealWindowEnd,
574	        ABOUT_WHO_SHOWCASE.mergeEnd,
575	      ),
576	    );
577	    const scatterProgress = this._easeOutCubic(
578	      Helpers.remap01(
579	        progress,
580	        ABOUT_WHO_SHOWCASE.mergeEnd,
581	        ABOUT_WHO_SHOWCASE.scatterEnd,
582	      ),
583	    );
584	
585	    const titleRevealOpacity = Helpers.lerp(
586	      ABOUT_WHO_SHOWCASE.titleOpacityStart,
587	      ABOUT_WHO_SHOWCASE.titleOpacityEnd,
588	      spawnProgress,
589	    );
590	    const titleOpacity = Helpers.lerp(
591	      titleRevealOpacity,
592	      ABOUT_WHO_SHOWCASE.titleExitOpacity,
593	      scatterProgress,
594	    );
595	    const titlePeakScale = Helpers.lerp(
596	      ABOUT_WHO_SHOWCASE.titleScaleStart,
597	      ABOUT_WHO_SHOWCASE.titleScalePeak,
598	      Math.max(spawnProgress, mergeProgress),
599	    );
600	    const titleScale = Helpers.lerp(
601	      titlePeakScale,
602	      ABOUT_WHO_SHOWCASE.titleScaleEnd,
603	      scatterProgress,
604	    );
605	    const titleY = Helpers.lerp(
606	      ABOUT_WHO_SHOWCASE.titleYOffsetPx,
607	      0,
608	      spawnProgress,
609	    ) + Helpers.lerp(0, ABOUT_WHO_SHOWCASE.titleExitYOffsetPx, scatterProgress);
610	
611	    const titleTransform = `translate3d(0, ${titleY}px, 0) scale(${titleScale})`;
612	    titleLayers.forEach((titleLayer) => {
613	      titleLayer.style.opacity = String(titleOpacity);
614	      titleLayer.style.transform = titleTransform;
615	    });
616	
617	    const ringOpacity =
618	      ABOUT_WHO_SHOWCASE.ringOpacityMax * Math.max(spawnProgress, mergeProgress);
619	    const ringScale = Helpers.lerp(
620	      ABOUT_WHO_SHOWCASE.ringScaleStart,
621	      ABOUT_WHO_SHOWCASE.ringScaleEnd,
622	      Math.max(spawnProgress, scatterProgress),
623	    );
624	    ring.style.opacity = String(ringOpacity);
625	    ring.style.transform = `translate3d(-50%, -50%, 0) scale(${ringScale})`;
626	
627	    cards.forEach((card, index) => {
628	      const pose = ABOUT_WHO_SHOWCASE.cardPoses[index];
629	      if (!pose) return;
630	      const revealStart =
631	        Helpers.lerp(
632	          ABOUT_WHO_SHOWCASE.cardRevealWindowStart,
633	          ABOUT_WHO_SHOWCASE.cardRevealWindowEnd,
634	          index / cardCount,
635	        );
636	      const revealEnd =
637	        Helpers.lerp(
638	          ABOUT_WHO_SHOWCASE.cardRevealWindowStart,
639	          ABOUT_WHO_SHOWCASE.cardRevealWindowEnd,
640	          (index + 1) / cardCount,
641	        );
642	      const cardRevealProgress = this._easeOutCubic(
643	        Helpers.remap01(progress, revealStart, revealEnd),
644	      );
645	      const orbitX =
646	        Math.cos(Helpers.degToRad(pose.orbitAngleDeg)) * pose.orbitRadiusVmin;
647	      const orbitY =
648	        Math.sin(Helpers.degToRad(pose.orbitAngleDeg)) *
649	        pose.orbitRadiusVmin *
650	        ABOUT_WHO_SHOWCASE.orbitVerticalScale;
651	      const orbitRotate = pose.orbitRotateDeg;
652	      const revealScale =
653	        pose.scale *
654	        this._easeOutBack(
655	          cardRevealProgress,
656	          ABOUT_WHO_SHOWCASE.cardRevealOvershoot,
657	        );
