760	    const ringOpacity =
761	      MAIN_WHY_SHOWCASE.ringOpacityMax * Math.max(spawnProgress, mergeProgress);
762	    const ringScale = Helpers.lerp(
763	      MAIN_WHY_SHOWCASE.ringScaleStart,
764	      MAIN_WHY_SHOWCASE.ringScaleEnd,
765	      Math.max(spawnProgress, scatterProgress),
766	    );
