1313	  private _staggerContactBlocks(
1314	    blocks: readonly HTMLElement[],
1315	    visible: boolean,
1316	  ): void {
1317	    blocks.forEach((block, index) => {
1318	      const timerId = window.setTimeout(() => {
1319	        if (visible) {
1320	          block.classList.remove("is-block-reveal-down");
1321	          BlockReveal.reveal(block);
1322	          return;
1323	        }
1324	        block.classList.add(INIT_DOM_CLASSES.blockBase);
1325	        block.classList.remove(INIT_DOM_CLASSES.blockUp);
1326	        block.classList.remove(BLOCK_HIDDEN_CLASS, INIT_DOM_CLASSES.boxHidden);
1327	        void block.getBoundingClientRect();
1328	        block.classList.add("is-block-reveal-down");
1329	      }, index * CONTACT_REVEAL_STAGGER_MS);
1330	      this._contactMotionTimerIds.push(timerId);
1331	    });
1332	  }
